import React, { useEffect, useState } from 'react';
import axios from 'axios';

import {
  fetchIncidents,
  createIncident,
  updateIncidentStatus,
  addIncidentComment,
  fetchIncidentById,
} from './api';
import IncidentList from './components/IncidentList';
import IncidentForm from './components/IncidentForm';
import IncidentDetail from './components/IncidentDetail';

function App() {
  const [incidents, setIncidents] = useState([]);
  const [filters, setFilters] = useState({ status: '', severity: '', search: '' });
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [limit] = useState(10);
  const [selectedIncidentId, setSelectedIncidentId] = useState(null);
  const [selectedIncident, setSelectedIncident] = useState(null);

  const [loading, setLoading] = useState(false);         // Loading state for spinner
  const [actionPending, setActionPending] = useState(false); // Disable buttons during API calls
  const [fadeIn, setFadeIn] = useState(false);           // For fade-in effect

  // Load incidents from API
  const loadIncidents = () => {
    setLoading(true);
    fetchIncidents({ ...filters, page, limit })
      .then(res => {
        setIncidents(res.data.incidents);
        setTotal(res.data.total);
        setLoading(false);
        setFadeIn(true);  // Animate fade-in on new data load
      })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    loadIncidents();
    window.scrollTo(0, 0);  // Scroll to top on page or filter change
  }, [filters, page]);

  const handleCreateIncident = (data) => {
    setActionPending(true);
    createIncident(data)
      .then(() => loadIncidents())
      .finally(() => setActionPending(false));
  };

  const handleSelectIncident = (id) => {
    setSelectedIncidentId(id);
    setLoading(true);
    fetchIncidentById(id)
      .then(res => {
        setSelectedIncident(res.data);
        setLoading(false);
        setFadeIn(true);
      })
      .catch(() => setLoading(false));
    window.scrollTo(0, 0);
  };

  const handleCloseDetail = () => {
    setSelectedIncidentId(null);
    setSelectedIncident(null);
    window.scrollTo(0, 0);
  };

  const handleStatusChange = (id, status) => {
    setActionPending(true);
    updateIncidentStatus(id, status)
      .then(() => {
        loadIncidents();
        if (selectedIncidentId === id) {
          fetchIncidentById(id).then(res => setSelectedIncident(res.data));
        }
      })
      .finally(() => setActionPending(false));
  };

  const handleAddComment = (id, text) => {
    setActionPending(true);
    addIncidentComment(id, text)
      .then(() => {
        fetchIncidentById(id).then(res => setSelectedIncident(res.data));
      })
      .finally(() => setActionPending(false));
  };

  return (
    <div className="App" style={{ padding: 20, fontFamily: 'Arial, sans-serif', maxWidth: 900, margin: '0 auto' }}>
      <h1 style={{textAlign: 'center', marginBottom: 30}}>Incident Desk Dashboard</h1>

      {loading && (
        <div style={{ textAlign: 'center', marginBottom: 20 }}>
          {/* Simple loading spinner */}
          <div className="spinner" style={{
            border: '4px solid #f3f3f3',
            borderTop: '4px solid #3498db',
            borderRadius: '50%',
            width: 30,
            height: 30,
            animation: 'spin 1s linear infinite',
            margin: 'auto'
          }} />
        </div>
      )}

      {!selectedIncidentId ? (
        <div style={{ opacity: fadeIn ? 1 : 0, transition: 'opacity 0.5s ease-in' }}>
          <IncidentForm onCreate={handleCreateIncident} disabled={actionPending} />
          {incidents.length === 0 && !loading ? (
            <p style={{textAlign: 'center', color: '#666', marginTop: 20}}>No incidents found matching filters.</p>
          ) : (
            <IncidentList
              incidents={incidents}
              total={total}
              page={page}
              limit={limit}
              onPageChange={setPage}
              onSelectIncident={handleSelectIncident}
              filters={filters}
              setFilters={setFilters}
              disabled={actionPending}
            />
          )}
        </div>
      ) : (
        <div style={{ opacity: fadeIn ? 1 : 0, transition: 'opacity 0.5s ease-in' }}>
          <IncidentDetail
            incident={selectedIncident}
            onClose={handleCloseDetail}
            onStatusChange={handleStatusChange}
            onAddComment={handleAddComment}
            disabled={actionPending}
          />
        </div>
      )}

      {/* Add keyframe animation for spinner */}
      <style>
        {`
          @keyframes spin {
            0% { transform: rotate(0deg);}
            100% { transform: rotate(360deg);}
          }
          /* Disabled style example */
          button:disabled, select:disabled, input:disabled, textarea:disabled {
            opacity: 0.5;
            cursor: not-allowed;
          }
        `}
      </style>
    </div>
  );
}

export default App;
